<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Plus, RotateCcw, Save, Trash2, UserRound, X } from 'lucide-vue-next'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import { ownersApi, type FiscalPeriodRecord, type OwnerRecord, type OwnerTransactionRecord } from '../api/owners'
import { accountingApi, type FinancialAccountRecord } from '../api/accounting'
import { formatMoney, formatMoneyInput, parseMoneyInput } from '../utils/currency'
import { formatDateTime } from '../utils/date'
import JalaliDatePicker from '../components/JalaliDatePicker.vue'

const props = defineProps<{ currencyUnit: 'Rial' | 'Toman' }>()
const emit = defineEmits<{ notify: [string] }>()
type Tab = 'Overview' | 'Owners' | 'Transactions' | 'Capital & Drawings' | 'Loans / Current Accounts' | 'Profit Allocation'
const tabs: Tab[] = ['Overview', 'Owners', 'Transactions', 'Capital & Drawings', 'Loans / Current Accounts', 'Profit Allocation']
const tab = ref<Tab>('Overview'); const owners = ref<OwnerRecord[]>([]); const transactions = ref<OwnerTransactionRecord[]>([]); const periods = ref<FiscalPeriodRecord[]>([]); const accounts = ref<FinancialAccountRecord[]>([])
const selectedOwner = ref<string>(''); const selectedPeriod = ref<string>(''); const error = ref(''); const editing = ref(false); const saving = ref(false)
const ownerForm = ref({ name: '', phone: '', email: '', notes: '', ownershipBps: 0, profitSharingBps: 0 })
const shareForm = ref({ ownershipBps: 0, profitSharingBps: 0 })
const txForm = ref({ type: 'capital_contribution', amountText: '', financialAccountId: '', categoryAccountId: 'ACC-EXP-OTHER', description: '', occurredAt: null as string|null, notes: '' })
const periodForm = ref({ name: '', startDate: null as string|null, endDate: null as string|null, notes: '' })
const currentOwner = computed(() => owners.value.find(x => x.id === selectedOwner.value) ?? null)
const selectedPeriodRow = computed(() => periods.value.find(x => x.id === selectedPeriod.value) ?? null)
const filteredTransactions = computed(() => transactions.value.filter(x => !selectedOwner.value || x.ownerId === selectedOwner.value))
const ownerName = (id:string) => owners.value.find(x => x.id === id)?.name ?? id
const money = (v:number) => formatMoney(v, props.currencyUnit)
async function load() { try { [owners.value, periods.value, accounts.value] = await Promise.all([ownersApi.list(false), ownersApi.periods(), accountingApi.financialAccounts()]); if (!selectedOwner.value) selectedOwner.value = owners.value[0]?.id ?? ''; if (!selectedPeriod.value) selectedPeriod.value = periods.value[0]?.id ?? ''; syncShares(); await loadTransactions() } catch (e) { error.value = String(e) } }
function syncShares(){if(currentOwner.value)shareForm.value={ownershipBps:currentOwner.value.ownershipBps,profitSharingBps:currentOwner.value.profitSharingBps}}
async function loadTransactions() { try { transactions.value = await ownersApi.transactions(selectedOwner.value) } catch (e) { error.value = String(e) } }
function startOwner() { ownerForm.value = { name:'', phone:'', email:'', notes:'', ownershipBps:0, profitSharingBps:0 }; editing.value = true; tab.value = 'Owners' }
async function saveOwner() { saving.value=true;try { const v=await ownersApi.create(ownerForm.value); owners.value=[v,...owners.value];selectedOwner.value=v.id;editing.value=false;emit('notify','Owner saved.')}catch(e){error.value=String(e)}finally{saving.value=false} }
async function saveShares(){if(!currentOwner.value)return;try{const v=await ownersApi.updateShares(currentOwner.value.id,shareForm.value);owners.value=owners.value.map(x=>x.id===v.id?v:x);emit('notify','Owner shares updated.')}catch(e){error.value=String(e)}}
async function setActive(){if(!currentOwner.value)return;try{if(currentOwner.value.active)await ownersApi.archive(currentOwner.value.id);else await ownersApi.reactivate(currentOwner.value.id);await load()}catch(e){error.value=String(e)}}
async function deleteOwner(){if(!currentOwner.value||!window.confirm('Delete this owner permanently when safe?'))return;try{await ownersApi.delete(currentOwner.value.id);owners.value=owners.value.filter(x=>x.id!==currentOwner.value!.id);selectedOwner.value=owners.value[0]?.id??'';emit('notify','Owner deleted.')}catch(e){error.value=String(e)}}
async function postTransaction() { if (!selectedOwner.value) return; const amount=parseMoneyInput(txForm.value.amountText,props.currencyUnit); if (amount===null||amount<=0){error.value='Enter a valid positive amount.';return} try { await ownersApi.createTransaction({...txForm.value,ownerId:selectedOwner.value,amountRial:amount}); await load(); emit('notify','Owner transaction posted.')} catch(e){error.value=String(e)} }
async function createPeriod() { try { const v=await ownersApi.createPeriod(periodForm.value);periods.value=[v,...periods.value];selectedPeriod.value=v.id;emit('notify','Fiscal period created.')}catch(e){error.value=String(e)} }
async function previewPeriod() { if(!selectedPeriod.value)return;try{const v=await ownersApi.previewPeriod(selectedPeriod.value);periods.value=periods.value.map(x=>x.id===v.id?v:x)}catch(e){error.value=String(e)} }
async function closePeriod() { if(!selectedPeriod.value||!window.confirm('Close this fiscal period permanently?'))return;try{const v=await ownersApi.closePeriod(selectedPeriod.value);periods.value=periods.value.map(x=>x.id===v.id?v:x);emit('notify','Fiscal period closed.')}catch(e){error.value=String(e)} }
onMounted(load)
</script>
<template>
  <div class="owners-view">
    <WorkspaceStickyStack><header class="workspace-heading"><div><p class="eyebrow">Finance / ownership</p><h1>Owners & fiscal periods</h1><p class="heading-description">Keep capital, current accounts, and period allocations authoritative in the ledger.</p></div><button class="button button-primary" type="button" @click="startOwner"><Plus :size="16"/> New owner</button></header><nav class="workspace-tabs" aria-label="Owner workspace"><button v-for="item in tabs" :key="item" type="button" :class="{active:tab===item}" @click="tab=item">{{ item }}</button></nav></WorkspaceStickyStack>
    <div v-if="error" class="form-error" role="alert">{{ error }} <button class="icon-button" @click="error=''" aria-label="Dismiss"><X :size="14"/></button></div>
    <section v-if="tab==='Overview'" class="owners-grid"><SectionPanel title="Ownership overview" subtitle="Balances are derived from posted journal lines."><div class="owner-cards"><button v-for="o in owners" :key="o.id" class="owner-card" :class="{selected:selectedOwner===o.id}" @click="selectedOwner=o.id;tab='Owners'"><UserRound :size="18"/><strong>{{o.name}}</strong><span>{{o.profitSharingBps/100}}% profit share</span><b>{{money(o.currentBalanceRial)}}</b></button></div></SectionPanel><SectionPanel title="Fiscal periods" subtitle="P&L is calculated only from journal lines."><div class="period-list"><button v-for="p in periods" :key="p.id" class="period-row" :class="{selected:selectedPeriod===p.id}" @click="selectedPeriod=p.id;tab='Profit Allocation'"><span><strong>{{p.name}}</strong><small>{{formatDateTime(p.startDate)}} – {{formatDateTime(p.endDate)}}</small></span><StatusBadge :label="p.status" :tone="p.status==='Closed'?'slate':'amber'"/><b>{{money(p.profitLossRial)}}</b></button><p v-if="!periods.length" class="inspector-empty-copy">No fiscal periods yet.</p></div></SectionPanel></section>
    <section v-else-if="tab==='Owners'" class="owners-grid"><SectionPanel title="Owner register" subtitle="Ownership and profit-sharing are independent fixed-scale percentages."><div class="table-wrap"><table class="data-table"><thead><tr><th>Owner</th><th>Ownership</th><th>Profit share</th><th>Current balance</th></tr></thead><tbody><tr v-for="o in owners" :key="o.id" :class="{'is-selected':selectedOwner===o.id}" @click="selectedOwner=o.id;syncShares()"><td><span class="table-primary">{{o.name}}</span><span class="table-secondary">{{o.active?'Active':'Archived'}}</span></td><td>{{o.ownershipBps/100}}%</td><td>{{o.profitSharingBps/100}}%</td><td>{{money(o.currentBalanceRial)}}</td></tr></tbody></table></div></SectionPanel><SectionPanel v-if="editing" title="New owner" subtitle="Percentages are stored as basis points, never floats."><form class="owner-form" @submit.prevent="saveOwner"><label class="form-field"><span>Name</span><input v-model="ownerForm.name" required /></label><div class="owner-form-grid"><label class="form-field"><span>Ownership % (bps)</span><input v-model.number="ownerForm.ownershipBps" type="number" min="0" max="10000" required /></label><label class="form-field"><span>Profit share % (bps)</span><input v-model.number="ownerForm.profitSharingBps" type="number" min="0" max="10000" required /></label></div><label class="form-field"><span>Phone</span><input v-model="ownerForm.phone" /></label><label class="form-field"><span>Email</span><input v-model="ownerForm.email" type="email" /></label><label class="form-field"><span>Notes</span><textarea v-model="ownerForm.notes" rows="3"/></label><div class="material-form-actions"><button class="button button-secondary" type="button" @click="editing=false">Cancel</button><button class="button button-primary" :disabled="saving"><Save :size="15"/> Save</button></div></form></SectionPanel><SectionPanel v-else-if="currentOwner" title="Owner inspector" subtitle="Posted history is immutable; corrections are reversals."><div class="inspector-heading"><div class="material-inspector-icon"><UserRound :size="19"/></div><div><h3>{{currentOwner.name}}</h3><p>{{currentOwner.ownershipBps/100}}% ownership · {{currentOwner.profitSharingBps/100}}% profit share</p></div></div><form class="owner-form" @submit.prevent="saveShares"><div class="owner-form-grid"><label class="form-field"><span>Ownership bps</span><input v-model.number="shareForm.ownershipBps" type="number" min="0" max="10000"/></label><label class="form-field"><span>Profit share bps</span><input v-model.number="shareForm.profitSharingBps" type="number" min="0" max="10000"/></label></div><button class="button button-secondary"><Save :size="15"/> Save future shares</button></form><dl class="inspector-details"><div><dt>Capital</dt><dd>{{money(currentOwner.capitalContributedRial)}}</dd></div><div><dt>Drawings</dt><dd>{{money(currentOwner.drawingsRial)}}</dd></div><div><dt>Current / payable</dt><dd>{{money(currentOwner.currentBalanceRial)}}</dd></div><div><dt>Loans payable</dt><dd>{{money(currentOwner.loanPayableRial)}}</dd></div><div><dt>Loans receivable</dt><dd>{{money(currentOwner.loanReceivableRial)}}</dd></div><div><dt>Allocated P/L</dt><dd>{{money(currentOwner.allocatedProfitLossRial)}}</dd></div></dl><div class="inspector-actions"><button class="button button-secondary" @click="tab='Transactions';loadTransactions">View transactions</button><button class="button button-secondary" @click="setActive"><RotateCcw :size="15"/> {{currentOwner.active?'Archive':'Reactivate'}}</button><button class="button button-danger" @click="deleteOwner"><Trash2 :size="15"/> Delete</button></div></SectionPanel></section>
    <section v-else-if="tab==='Transactions'||tab==='Capital & Drawings'||tab==='Loans / Current Accounts'" class="owners-grid"><SectionPanel title="Post owner transaction" subtitle="Every action becomes one balanced integer-Rial journal entry."><form class="owner-form" @submit.prevent="postTransaction"><label class="form-field"><span>Owner</span><select v-model="selectedOwner" required><option v-for="o in owners" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label class="form-field"><span>Type</span><select v-model="txForm.type"><option value="capital_contribution">Capital contribution</option><option value="drawing">Drawing (not an expense)</option><option value="owner_paid_expense">Business expense paid personally</option><option value="owner_reimbursement">Owner reimbursement</option><option value="loan_to_business">Owner → business loan</option><option value="loan_from_business">Business → owner loan</option><option value="loan_repayment_to_owner">Repay owner loan</option><option value="loan_repayment_from_owner">Receive owner loan repayment</option></select></label><label class="form-field"><span>Amount ({{currencyUnit}})</span><input v-model="txForm.amountText" inputmode="decimal" required @blur="txForm.amountText=formatMoneyInput(parseMoneyInput(txForm.amountText,currencyUnit)||0,currencyUnit)" /></label><label v-if="txForm.type!=='owner_paid_expense'" class="form-field"><span>Cash / bank account</span><select v-model="txForm.financialAccountId" required><option value="">Select account</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label v-else class="form-field"><span>Expense category account</span><input v-model="txForm.categoryAccountId" required /></label><label class="form-field"><span>Description</span><input v-model="txForm.description" /></label><button class="button button-primary">Post transaction</button></form></SectionPanel><SectionPanel title="Owner transaction history" subtitle="Derived balances remain stable after reversals."><div class="table-wrap"><table class="data-table"><thead><tr><th>Number</th><th>Owner</th><th>Type</th><th>Amount</th><th>Date</th><th></th></tr></thead><tbody><tr v-for="x in filteredTransactions" :key="x.id"><td>{{x.transactionNumber}}</td><td>{{ownerName(x.ownerId)}}</td><td>{{x.type}}</td><td>{{money(x.amountRial)}}</td><td>{{formatDateTime(x.occurredAt)}}</td><td><button v-if="x.status==='Posted'" class="text-button" @click="ownersApi.reverseTransaction(x.id).then(load)">Reverse</button></td></tr></tbody></table></div></SectionPanel></section>
    <section v-else-if="tab==='Profit Allocation'" class="owners-grid">
      <SectionPanel title="Fiscal periods" subtitle="Close once; the profit-sharing snapshot is preserved forever.">
        <div class="period-list"><button v-for="p in periods" :key="p.id" class="period-row" :class="{selected:selectedPeriod===p.id}" @click="selectedPeriod=p.id"><span><strong>{{p.name}}</strong><small>{{formatDateTime(p.startDate)}} – {{formatDateTime(p.endDate)}}</small></span><StatusBadge :label="p.status" :tone="p.status==='Closed'?'slate':'amber'"/><b>{{money(p.profitLossRial)}}</b></button></div>
        <form class="owner-form" @submit.prevent="createPeriod"><h3>New period</h3><label class="form-field"><span>Name</span><input v-model="periodForm.name" required placeholder="1405"/></label><div class="owner-form-grid"><label class="form-field"><span>Start date</span><JalaliDatePicker v-model="periodForm.startDate" /></label><label class="form-field"><span>End date</span><JalaliDatePicker v-model="periodForm.endDate" /></label></div><button class="button button-secondary">Create period</button></form>
      </SectionPanel>
      <SectionPanel v-if="selectedPeriodRow" title="Closing preview" subtitle="Revenue − COGS − expenses, from journal lines only."><dl class="inspector-details"><div><dt>Revenue</dt><dd>{{money(selectedPeriodRow.revenueRial)}}</dd></div><div><dt>COGS</dt><dd>{{money(selectedPeriodRow.cogsRial)}}</dd></div><div><dt>Expenses</dt><dd>{{money(selectedPeriodRow.expensesRial)}}</dd></div><div><dt>Profit / loss</dt><dd>{{money(selectedPeriodRow.profitLossRial)}}</dd></div></dl><div class="period-actions"><button class="button button-secondary" @click="previewPeriod">Refresh preview</button><button v-if="selectedPeriodRow.status==='Open'" class="button button-primary" @click="closePeriod">Close period</button></div><h3>Owner allocation</h3><div v-for="a in (selectedPeriodRow.previewAllocations?.length?selectedPeriodRow.previewAllocations:selectedPeriodRow.allocations)" :key="a.ownerId" class="period-row"><span>{{ownerName(a.ownerId)}} · {{a.profitSharingBps/100}}%</span><b>{{money(a.amountRial)}}</b></div></SectionPanel>
    </section>
  </div>
</template>
